using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Security;
using System.Net.Sockets;
using System.Security.Authentication;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace VaultBridge {
    static class TransferTests {
        static int passed;
        static List<string> lines;
        static void Check(bool condition,string message){if(!condition)throw new Exception(message);passed++;lines.Add("PASS: "+message);}
        static void Reject(Action action,string message){bool rejected=false;try{action();}catch(IOException){rejected=true;}Check(rejected,message);}
        sealed class WaitingInput : Stream {
            internal readonly ManualResetEventSlim Entered=new ManualResetEventSlim(),Release=new ManualResetEventSlim();
            readonly MemoryStream bytes;internal Action BeforeRead;
            internal WaitingInput(byte[] data){bytes=new MemoryStream(data);}
            public override int Read(byte[] buffer,int offset,int count){Entered.Set();if(!Release.Wait(5000))throw new IOException("test input wait expired");if(BeforeRead!=null){Action run=BeforeRead;BeforeRead=null;run();}return bytes.Read(buffer,offset,count);}
            public override void Write(byte[] buffer,int offset,int count){}public override void Flush(){}public override bool CanRead{get{return true;}}public override bool CanSeek{get{return false;}}public override bool CanWrite{get{return true;}}public override long Length{get{throw new NotSupportedException();}}public override long Position{get{throw new NotSupportedException();}set{throw new NotSupportedException();}}public override long Seek(long offset,SeekOrigin origin){throw new NotSupportedException();}public override void SetLength(long value){throw new NotSupportedException();}
        }
        static Dictionary<string,object> Call(VaultServer server,object request,byte[] upload){
            using(TcpClient client=new TcpClient()){client.Connect(IPAddress.Loopback,server.Port);using(SslStream ssl=new SslStream(client.GetStream(),false,(s,c,ch,e)=>Crypto.Equal(Crypto.Fingerprint(new System.Security.Cryptography.X509Certificates.X509Certificate2(c)),server.Fingerprint))){ssl.AuthenticateAsClient("VaultBridge",null,SslProtocols.Tls12,false);Wire.Write(ssl,request);Dictionary<string,object> reply=Wire.Read(ssl);if(upload!=null&&(bool)reply["ok"]){ssl.Write(upload,0,upload.Length);ssl.Flush();reply=Wire.Read(ssl);}return reply;}}
        }
        public static int Run(string workspace,string java,string classpath){
            passed=0;lines=new List<string>();string root=Path.Combine(workspace,"transfer-"+Guid.NewGuid().ToString("N")),vault=Path.Combine(root,"vault"),inbox=Path.Combine(root,"inbox"),staging=Path.Combine(root,"tasks");Directory.CreateDirectory(vault);Directory.CreateDirectory(inbox);
            Check(TransferRules.Count(TransferRules.MaxFile)==2048,"8 GiB uses 2048 bounded chunks");Check(TransferRules.Count(0)==0,"empty files have no blocks");Reject(()=>TransferRules.Count(TransferRules.MaxFile+1),"file beyond 8 GiB rejected");Reject(()=>TransferRules.Count(-1),"negative size rejected");Reject(()=>TransferRules.Length(1,1),"out-of-range block rejected");
            string hash=Crypto.Hash(new MemoryStream(new byte[]{1,2,3}));Reject(()=>TransferRules.Validate(new List<FileItem>{new FileItem{path=".obsidian/config.json",size=3,sha256=hash}}),"hidden configuration rejected for uploads");Reject(()=>TransferRules.Validate(new List<FileItem>{new FileItem{path="A.md",size=3,sha256=hash},new FileItem{path="a.md",size=3,sha256=hash}}),"case-folded duplicate upload paths rejected");
            Settings state=new Settings{vault=vault,port=0};string owner=Crypto.RandomToken();state.devices.Add(new Device{name="test",token=owner,pairedAt=DateTime.UtcNow.ToString("o")});string other=Crypto.RandomToken();state.devices.Add(new Device{name="other",token=other,pairedAt=DateTime.UtcNow.ToString("o")});
            TransferHub hub=new TransferHub(staging,state,j=>{},s=>{});byte[] bytes=new byte[TransferRules.Chunk+17];new Random(27183).NextBytes(bytes);string expected=Crypto.Hash(new MemoryStream(bytes));string id=Guid.NewGuid().ToString("N");FileItem[] files={new FileItem{path="笔记.md",size=bytes.Length,sha256=expected}};
            using(VaultServer server=new VaultServer(state,()=>{},s=>{})){
                server.Transfers=hub;server.Start(true);
                Dictionary<string,object> request=Call(server,new{action="x-request",token=owner,id=id,mode="notes",prefix="回传",files=files},null);Check((bool)request["ok"]&&Wire.Text(request,"state")=="pending","new receive requires explicit approval");
                byte[] first=bytes.Take(TransferRules.Chunk).ToArray();string firstHash=Crypto.Hash(new MemoryStream(first));
                Check(!(bool)Call(server,new{action="x-put",token=owner,id=id,file=0,block=0,sha256=firstHash},first)["ok"],"paired read permission does not permit a pending upload");
                Check(!(bool)Call(server,new{action="x-status",token=other,id=id,file=0},null)["ok"],"receive task is bound to originating device");
                hub.Approve(id,vault,true);Check((bool)Call(server,new{action="x-put",token=owner,id=id,file=0,block=0,sha256=firstHash},first)["ok"],"approved block accepted and verified");
                Check(!File.Exists(Path.Combine(vault,"回传","笔记.md")),"incomplete file does not appear in PC vault");
                Check(!(bool)Call(server,new{action="x-commit",token=owner,id=id,file=0},null)["ok"],"commit refuses missing blocks");
                Check((bool)Call(server,new{action="x-has",token=owner,id=id,file=0,block=0,sha256=firstHash},null)["present"],"acknowledgement loss can query already verified block");
                File.WriteAllBytes(Path.Combine(staging,id,"0-0-"+firstHash+".block"),new byte[]{0});Check(!(bool)Call(server,new{action="x-has",token=owner,id=id,file=0,block=0,sha256=firstHash},null)["present"],"corrupt persisted block is not treated as complete");
                Check((bool)Call(server,new{action="x-put",token=owner,id=id,file=0,block=0,sha256=firstHash},first)["ok"],"corrupt block can be replaced with verified retry");
                byte[] last=bytes.Skip(TransferRules.Chunk).ToArray();string lastHash=Crypto.Hash(new MemoryStream(last));Check((bool)Call(server,new{action="x-put",token=owner,id=id,file=0,block=1,sha256=lastHash},last)["ok"],"final short block accepted");
                Directory.CreateDirectory(Path.Combine(vault,"回传"));File.WriteAllText(Path.Combine(vault,"回传","笔记.md"),"PC master content");
                Dictionary<string,object> committed=Call(server,new{action="x-commit",token=owner,id=id,file=0},null);Check((bool)committed["ok"]&&Wire.Text(committed,"saved").Contains("VaultBridge 1"),"same-name changed note is saved separately");Check(File.ReadAllText(Path.Combine(vault,"回传","笔记.md"))=="PC master content","computer master note remains unchanged");Check(Crypto.HashFile(Paths.Resolve(vault,Wire.Text(committed,"saved")))==expected,"committed file matches whole-file SHA-256");
                Check(Wire.Text(Call(server,new{action="x-commit",token=owner,id=id,file=0},null),"saved")==Wire.Text(committed,"saved"),"commit replay is idempotent");
                server.Transfers=new TransferHub(staging,state,j=>{},s=>{});Check((bool)Call(server,new{action="x-status",token=owner,id=id,file=0},null)["done"],"completed receive survives reconstructed server state");
                string corruptId=Guid.NewGuid().ToString("N");Call(server,new{action="x-request",token=owner,id=corruptId,mode="files",prefix="",files=files},null);Reject(()=>server.Transfers.Approve(corruptId,vault,true),"ordinary inbox cannot silently write PC vault");server.Transfers.Approve(corruptId,inbox,false);Check(Wire.Text(Call(server,new{action="x-status",token=owner,id=corruptId,file=0},null),"state")=="rejected","rejected receive remains rejected");
                string ancestorId=Guid.NewGuid().ToString("N");FileItem[] nested={new FileItem{path="vault/ordinary.md",size=0,sha256=Crypto.Hash(new MemoryStream())}};Call(server,new{action="x-request",token=owner,id=ancestorId,mode="files",prefix="",files=nested},null);Reject(()=>server.Transfers.Approve(ancestorId,root,true),"ordinary ancestor inbox cannot enter vault through file path");server.Transfers.Approve(ancestorId,root,false);
                string prefixId=Guid.NewGuid().ToString("N");FileItem[] empty={new FileItem{path="ordinary.md",size=0,sha256=Crypto.Hash(new MemoryStream())}};Call(server,new{action="x-request",token=owner,id=prefixId,mode="files",prefix="vault",files=empty},null);Reject(()=>server.Transfers.Approve(prefixId,root,true),"ordinary prefix cannot enter vault");server.Transfers.Approve(prefixId,root,false);
                string movedId=Guid.NewGuid().ToString("N");Call(server,new{action="x-request",token=owner,id=movedId,mode="files",prefix="",files=empty},null);server.Transfers.Approve(movedId,inbox,true);state.vault=inbox;Check(!(bool)Call(server,new{action="x-commit",token=owner,id=movedId,file=0},null)["ok"]&&!File.Exists(Path.Combine(inbox,"ordinary.md")),"commit rechecks vault boundary after settings change");state.vault=vault;server.Transfers.Revoke(movedId);
                var snapshots=server.Transfers.Snapshot();snapshots[0].saved["poison"]="unexpected";snapshots[0].state="unexpected";Check(server.Transfers.Snapshot().All(j=>j.state!="unexpected"&&!j.saved.ContainsKey("poison")),"task window receives independent immutable metadata snapshots");
                string blockedId=Guid.NewGuid().ToString("N");FileItem[] tiny={new FileItem{path="waiting.bin",size=3,sha256=hash}};Call(server,new{action="x-request",token=owner,id=blockedId,mode="files",prefix="",files=tiny},null);server.Transfers.Approve(blockedId,inbox,true);TransferHub currentHub=server.Transfers;
                WaitingInput stalled=new WaitingInput(new byte[]{1,2,3});Task reading=Task.Run(()=>currentHub.Handle("x-put",Json.Decode<Dictionary<string,object>>(Json.Encode(new{id=blockedId,file=0,block=0,sha256=hash})),stalled,owner));
                try{Check(stalled.Entered.Wait(1000),"production upload waits inside isolated task lock");Task<List<TransferJob>> view=Task.Run(()=>currentHub.Snapshot());Check(view.Wait(1000)&&view.Result.Count>0,"task snapshots respond while another upload waits for payload");string anotherId=Guid.NewGuid().ToString("N");Task otherRequest=Task.Run(()=>Call(server,new{action="x-request",token=owner,id=anotherId,mode="files",prefix="",files=tiny},null));Check(otherRequest.Wait(1000),"independent receive request is not blocked by stalled upload");}finally{stalled.Release.Set();reading.GetAwaiter().GetResult();}
                string revokingId=Guid.NewGuid().ToString("N");Call(server,new{action="x-request",token=owner,id=revokingId,mode="files",prefix="",files=tiny},null);currentHub.Approve(revokingId,inbox,true);WaitingInput revoking=new WaitingInput(new byte[]{1,2,3});revoking.BeforeRead=()=>currentHub.Revoke(revokingId);revoking.Release.Set();Reject(()=>currentHub.Handle("x-put",Json.Decode<Dictionary<string,object>>(Json.Encode(new{id=revokingId,file=0,block=0,sha256=hash})),revoking,owner),"in-flight block checks revocation again after payload read");Check(!(bool)Call(server,new{action="x-commit",token=owner,id=revokingId,file=0},null)["ok"]&&!File.Exists(Path.Combine(inbox,"waiting.bin")),"revoked receive cannot publish target file");
                string raceA=Guid.NewGuid().ToString("N"),raceB=Guid.NewGuid().ToString("N");byte[] secondBytes={4,5,6};string secondHash=Crypto.Hash(new MemoryStream(secondBytes));foreach(string raceId in new[]{raceA,raceB}){string contentHash=raceId==raceA?hash:secondHash;FileItem[] racing={new FileItem{path="concurrent.bin",size=3,sha256=contentHash}};Call(server,new{action="x-request",token=owner,id=raceId,mode="files",prefix="",files=racing},null);currentHub.Approve(raceId,inbox,true);Call(server,new{action="x-put",token=owner,id=raceId,file=0,block=0,sha256=contentHash},raceId==raceA?new byte[]{1,2,3}:secondBytes);}
                var raceFirst=Task.Run(()=>Call(server,new{action="x-commit",token=owner,id=raceA,file=0},null));var raceSecond=Task.Run(()=>Call(server,new{action="x-commit",token=owner,id=raceB,file=0},null));Task.WaitAll(raceFirst,raceSecond);var resultA=raceFirst.Result;var resultB=raceSecond.Result;if(!(bool)resultA["ok"])resultA=Call(server,new{action="x-commit",token=owner,id=raceA,file=0},null);if(!(bool)resultB["ok"])resultB=Call(server,new{action="x-commit",token=owner,id=raceB,file=0},null);Check((bool)resultA["ok"]&&(bool)resultB["ok"]&&Wire.Text(resultA,"saved")!=Wire.Text(resultB,"saved"),"concurrent same-name receives recover as separate saved files");Check(Crypto.HashFile(Paths.Resolve(inbox,Wire.Text(resultA,"saved")))==hash&&Crypto.HashFile(Paths.Resolve(inbox,Wire.Text(resultB,"saved")))==secondHash,"concurrent receive preserves both distinct contents without overwrite");
                string outgoing=Path.Combine(root,"large-example.bin");using(FileStream output=new FileStream(outgoing,FileMode.CreateNew))output.SetLength(270L*1024*1024);string rawZip=Path.Combine(root,"raw.zip");File.WriteAllBytes(rawZip,new byte[0]);server.Transfers.Publish(new[]{outgoing,rawZip});Check((bool)Call(server,new{action="x-list",token=owner},null)["ok"],"generic list includes file larger than legacy limit and raw ZIP");
                if(java!=null&&classpath!=null){
                    TransferHub auto=new TransferHub(staging,state,j=>{},s=>{});TransferHub approvedHub=null;approvedHub=new TransferHub(Path.Combine(root,"interop-tasks"),state,j=>approvedHub.Approve(j.id,j.mode=="notes"?vault:inbox,true),s=>{});approvedHub.Publish(new[]{outgoing,rawZip});server.Transfers=approvedHub;server.RenewPairing();
                    System.Diagnostics.ProcessStartInfo info=new System.Diagnostics.ProcessStartInfo(java,"-cp \""+classpath+"\" io.vaultbridge.app.TransferTest \""+root+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};
                    using(System.Diagnostics.Process process=System.Diagnostics.Process.Start(info)){process.StandardInput.WriteLine(server.PairingText("127.0.0.1"));process.StandardInput.Close();string output=process.StandardOutput.ReadToEnd(),error=process.StandardError.ReadToEnd();process.WaitForExit();lines.Add(output.Trim());Check(process.ExitCode==0,"actual Java transfer client interoperates with PC: "+(process.ExitCode==0?"success":error));}
                    Check(Directory.EnumerateFiles(Path.Combine(vault,"平板来件")).Any(),"manual note upload reaches chosen vault subdirectory");
                }
            }
            lines.Add("Transfer tests passed: "+passed);File.WriteAllLines(Path.Combine(workspace,"transfer-results.txt"),lines,new UTF8Encoding(false));return passed;
        }
    }
}
